item.command:
/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, a=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));
  always #5 clk = ~clk;

  task shiftbit(input bit b);
    begin
      a = b;
      #10;
      "'$display("t=%0t a=%0b a_tem=%08b match=%0b", $time, a, dut.a_tem, match);
    end
  endtask

  initial begin
    #2; rst_n = 0; a = 0;
    #8; rst_n = 1;
    // shift 01110001
    shiftbit(0);
    shiftbit(1);
    shiftbit(1);
    shiftbit(1);
    shiftbit(0);
    shiftbit(0);
    shiftbit(0);
    shiftbit(1);
    #10;
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

